python3 << 'EOF'
import pandas as pd
import numpy as np
import json

# Load data
df = pd.read_csv('/app/benchmark/data.csv', encoding='utf-8-sig')

apps = ['ChatGPT', 'Claude', 'Google_Gemini', 'Microsoft_Copilot', 'Perplexity']

# 1. Average Star Rating by App
star_data = {}
for app in apps:
    app_df = df[df['App'] == app]
    star_data[app] = {
        'avg_star': round(app_df['Star_Rating'].mean(), 3),
        'std_star': round(app_df['Star_Rating'].std(), 3),
        'n_reviews': len(app_df)
    }

# 2. Mean Sentiment Polarity by App
sentiment_data = {}
for app in apps:
    app_df = df[df['App'] == app]
    sentiment_data[app] = {
        'avg_sentiment': round(app_df['Sentiment_Polarity'].mean(), 3),
        'std_sentiment': round(app_df['Sentiment_Polarity'].std(), 3)
    }

# 3. Theme breakdown by app
themes = ['General', 'Pricing/Subscription', 'Bugs/Performance', 'Accuracy/Logic Issues']
theme_pct_data = {}
for app in apps:
    app_df = df[df['App'] == app]
    theme_pct_data[app] = {}
    total = len(app_df)
    for theme in themes:
        count = len(app_df[app_df['Review_Theme'] == theme])
        theme_pct_data[app][theme] = round(count / total * 100, 1) if total > 0 else 0

# 4. Sentiment-Rating Mismatch Rate
mismatch_data = {}
for app in apps:
    app_df = df[df['App'] == app].copy()

    def get_mismatch(row):
        stars = row['Star_Rating']
        sentiment = row['Sentiment_Polarity']
        if stars >= 4 and sentiment < -0.3:
            return 'high_stars_neg_sentiment'
        elif stars <= 2 and sentiment > 0.3:
            return 'low_stars_pos_sentiment'
        return 'match'

    app_df['mismatch_type'] = app_df.apply(get_mismatch, axis=1)
    total = len(app_df)
    match_count = len(app_df[app_df['mismatch_type'] == 'match'])
    mismatch_data[app] = {
        'high_stars_neg': round(len(app_df[app_df['mismatch_type'] == 'high_stars_neg_sentiment']) / total * 100, 2),
        'low_stars_pos': round(len(app_df[app_df['mismatch_type'] == 'low_stars_pos_sentiment']) / total * 100, 2),
        'total_mismatch_rate': round((total - match_count) / total * 100, 2)
    }

# 5. Review Engagement
thumbs_data = {}
for app in apps:
    app_df = df[df['App'] == app]
    thumbs_data[app] = {
        'mean': round(app_df['Thumbs_Up_Count'].mean(), 3),
        'median': round(app_df['Thumbs_Up_Count'].median(), 3)
    }

# 6. Rating distribution
rating_dist_data = {}
for app in apps:
    app_df = df[df['App'] == app]
    total = len(app_df)
    rating_dist_data[app] = {}
    for rating in range(1, 6):
        count = len(app_df[app_df['Star_Rating'] == rating])
        rating_dist_data[app][str(rating)] = round(count / total * 100, 1)

# 7. Review length stats
length_data = {}
for app in apps:
    app_df = df[df['App'] == app]
    length_data[app] = {
        'avg_words': round(app_df['Word_Count'].mean(), 1),
        'median_words': round(app_df['Word_Count'].median(), 1),
        'avg_chars': round(app_df['Review_Length_Chars'].mean(), 1)
    }

results = {
    'star_ratings': star_data,
    'sentiment_scores': sentiment_data,
    'theme_pct': theme_pct_data,
    'mismatch_rates': mismatch_data,
    'thumbs_by_app': thumbs_data,
    'rating_distribution': rating_dist_data,
    'length_stats': length_data,
    'total_reviews': len(df)
}

with open('/app/output/kpi_data.json', 'w') as f:
    json.dump(results, f, indent=2)

print("KPIs computed and saved successfully")
print(f"\nTotal reviews: {len(df):,}")
print(f"\n=== STAR RATINGS ===")
for app, data in star_data.items():
    print(f"  {app}: {data['avg_star']:.3f} (n={data['n_reviews']:,})")
print(f"\n=== SENTIMENT POLARITY ===")
for app, data in sentiment_data.items():
    print(f"  {app}: {data['avg_sentiment']:.3f}")
print(f"\n=== MISMATCH RATES ===")
for app, data in mismatch_data.items():
    print(f"  {app}: {data['total_mismatch_rate']:.2f}% ({data['high_stars_neg']:.2f}% high-star neg, {data['low_stars_pos']:.2f}% low-star pos)")
EOF

